<?php require "../config.php";$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$pdo->prepare("SELECT * FROM users WHERE email=?");$s->execute([trim($_POST["email"])]);$u=$s->fetch(PDO::FETCH_ASSOC);if($u&&password_verify($_POST["password"],$u["password"])){$_SESSION["user_id"]=$u["id"];$_SESSION["user_name"]=$u["name"];header("Location: dashboard.php");exit;}$error="Invalid email or password.";}?><!doctype html><html><head><title>Login</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="form panel"><h2>Citizen Login</h2><?php if($error):?><div class="error"><?=$error?></div><?php endif;?><form method="post"><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Password" required><button class="btn">Login</button></form><a href="register.php">Create account</a></div></body></html>